import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Filter features with strong association (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Using types as proxy for effect size - convert to float if needed
        try:
            effect_size = float(feats.types[i])
            if abs(effect_size) > 0.01:  
                strong_features.append(fid)
        except (ValueError, TypeError):
            # If types is not numeric, skip this feature
            continue

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = [
        ('PNU10', 'TSP11'), ('MSEQ10', 'LIZP11P'), ('MSEQ10', 'WCQF6'),
        ('WCQF6', 'LIZP11P'), ('JMD15', 'CZEW19'), ('OMB12A', 'WUL6'),
        ('OMB12A', 'UZFR6'), ('CTM15', 'NESJ4'), ('PFS16', 'ERV8'),
        ('WUL6', 'UZFR6'), ('MSEQ10', 'CZEW19'), ('CZER19B', 'EATE2A'),
        ('VRKS3', 'HWX7L'), ('CZER19B', 'IIH16'), ('ZSTN15L', 'LIZP11P'),
        ('CTM15', 'JMD15'), ('WCQF6', 'CZEW19'), ('MSEQ10', 'ZSTN15L'),
        ('JPO19', 'EATE2A'), ('ZSTN15L', 'WCQF6')
    ]

    # Keep only one feature from each correlated pair (prefer stronger)
    kept_features = set()
    for a, b in correlated_pairs:
        if a in feats.ids and b in feats.ids:
            # Prefer the one with higher absolute effect size
            idx_a = feats.column(a)
            idx_b = feats.column(b)
            effect_a = abs(np.mean(feats.x[feats.y==1, idx_a]) - np.mean(feats.x[feats.y==0, idx_a]))
            effect_b = abs(np.mean(feats.x[feats.y==1, idx_b]) - np.mean(feats.x[feats.y==0, idx_b]))
            kept_features.add(a if effect_a >= effect_b else b)
        elif a in feats.ids:
            kept_features.add(a)
        elif b in feats.ids:
            kept_features.add(b)

    # Add remaining features to kept_features
    for fid in strong_features:
        if fid not in kept_features:
            kept_features.add(fid)

    # Use all kept features for logistic regression
    cols = tuple(kept_features)

    # Find top features by mutual information
    if len(cols) > 0:
        mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in cols]], feats.y)
        sorted_indices = np.argsort(mi_scores)[::-1]

        # Select top drivers
        drivers = tuple([cols[i] for i in sorted_indices[:MAX_DRIVERS]])

        # Create products of top drivers
        products = []
        for i in range(len(drivers)):
            for j in range(i+1, len(drivers)):
                products.append((drivers[i], drivers[j]))

        # Weighted score using top features
        loadings = {}
        for i, fid in enumerate(cols):
            if i < len(sorted_indices):
                loadings[fid] = mi_scores[sorted_indices[i]]
    else:
        drivers = ()
        products = ()
        loadings = {}

    return Design(drivers=drivers, columns=cols, products=products, loadings=loadings)
